    void boundariesAccepted() {
        assertThat(post("/api/products", body("a", 1, 0)).status()).isEqualTo(201);
        assertThat(post("/api/products", body("a".repeat(100), 10_000_000, 1_000_000)).status()).isEqualTo(201);
    }

