                {"x", 100, "many"},
                {1234, 100, 1},
        };
        for (Object[] c : cases) {
            Res r = post("/api/products", body(c[0], c[1], c[2]));
            assertThat(r.status()).as("case %s/%s/%s", c[0], c[1], c[2]).isEqualTo(400);
            assertThat(r.code()).isEqualTo("VALIDATION_ERROR");
