        assertThat(createOrder("u1", "k-" + uniq(), items(p, 3, q, 4), coupon).status()).isEqualTo(201);

        assertThat(productOf(p).get("reserved").asLong()).isEqualTo(3);
        assertThat(productOf(p).get("available").asLong()).isEqualTo(7);
