        JsonNode o = order(items(p, 1000), coupon("RATE", 33, 0, null, 10));
        assertThat(o.get("subtotal").asLong()).isEqualTo(10_000_000_000L);
        assertThat(o.get("discount").asLong()).isEqualTo(3_300_000_000L);
