    @Test
    @DisplayName("R2.6 결제 거절(PAYMENT_FAILED)에서도 쿠폰 사용이 복원된다")
    void couponRestoredOnDecline() {
        long p = product(1000, 10);
        String code = coupon("FIXED", 100, 0, null, 3);
