        Res otherBody = createOrder("u1", key, items(p, 2), null);
        Res otherUser = createOrder("u2", key, items(p, 1), null);

        assertThat(otherBody.status()).isEqualTo(422);
        assertThat(otherBody.code()).isEqualTo("IDEMPOTENCY_KEY_MISMATCH");
