            Thread.sleep(25);
            inProgress = pay(id, "tok_ok", key);
        }
        first.join();
        assertThat(inProgress).isNotNull();
        assertProblem(inProgress, 409, "IDEMPOTENCY_IN_PROGRESS");

        assertProblem(pay(id, "tok_other", key), 422, "IDEMPOTENCY_KEY_MISMATCH");
